function escapeHtml(value) {
  return String(value || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
const item = $input.first().json;
const headers = item.headers || {};
const source = item.body && typeof item.body === 'object' && item.body.event ? item.body : item;
const payload = {
  event: source.event,
  requestId: source.requestId,
  createdAt: source.createdAt,
  customer: source.customer,
  service: source.service,
  photos: source.photos,
  actions: source.actions
};
const timestamp = String(headers['x-homestead-timestamp'] || '');
const now = Math.floor(Date.now() / 1000);
const ts = Number(timestamp);
const timestampValid = Boolean(timestamp) && Number.isFinite(ts) && Math.abs(now - ts) <= 300;
if (!timestampValid) {
  return [{ json: { httpStatus: 401, sendTelegram: false, photoMode: 'none', photoUrls: [], response: { ok: false, error: 'unauthorized' } } }];
}
const requestId = String(payload.requestId || '');
const eventName = String(payload.event || '');
if (eventName !== 'service_request.created' || !/^HS-\d{4}-\d{6}$/.test(requestId) || !payload.customer || !payload.service) {
  return [{ json: { httpStatus: 400, sendTelegram: false, photoMode: 'none', photoUrls: [], response: { ok: false, error: 'invalid_payload' } } }];
}
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const seenKey = eventName + ':' + requestId;
const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;
for (const key of Object.keys(staticData.seen)) {
  if (staticData.seen[key] < cutoff) delete staticData.seen[key];
}
if (staticData.seen[seenKey]) {
  return [{ json: { duplicate: true, httpStatus: 200, sendTelegram: false, photoMode: 'none', photoUrls: [], requestId, response: { ok: true, duplicate: true, requestId } } }];
}
staticData.seen[seenKey] = Date.now();
const customer = payload.customer || {};
const service = payload.service || {};
const photos = payload.photos || {};
const actions = payload.actions || {};
const created = payload.createdAt ? new Date(payload.createdAt) : new Date();
const when = new Intl.DateTimeFormat('es-PA', { timeZone: 'America/Panama', day: '2-digit', month: '2-digit', year: 'numeric', hour: 'numeric', minute: '2-digit' }).format(created);
const items = Array.isArray(photos.items) ? photos.items : [];
const photoUrls = [];
for (const entry of items) {
  const photoUrl = String(entry && entry.url || '');
  if (photoUrl.indexOf('https://') === 0) photoUrls.push(photoUrl);
}
if (photoUrls.length > 6) photoUrls.length = 6;
const photoMode = photoUrls.length === 0 ? 'none' : photoUrls.length === 1 ? 'single' : 'group';
const lines = ['🏠 <b>HOMESTEAD SERVICES</b>', '', '🔔 NUEVA SOLICITUD', '', '🆔 ' + escapeHtml(requestId)];
if (customer.name) lines.push('', '👤 ' + escapeHtml(customer.name));
if (service.type) lines.push('🛠 ' + escapeHtml(service.type));
if (service.property) lines.push('📍 ' + escapeHtml(service.property));
if (customer.phone) lines.push('', '📞 ' + escapeHtml(customer.phone));
if (customer.email) lines.push('✉️ ' + escapeHtml(customer.email));
if (service.description) lines.push('', '💬', escapeHtml(service.description));
if (photoUrls.length === 1) lines.push('', '📸 1 fotografía adjunta');
if (photoUrls.length > 1) lines.push('', '📸 ' + photoUrls.length + ' fotografías adjuntas');
lines.push('', '🕐 ' + escapeHtml(when));
const keyboard = { inline_keyboard: [] };
if (actions.replyUrl && String(actions.replyUrl).indexOf('https://') === 0) keyboard.inline_keyboard.push([{ text: '📧 RESPONDER', url: String(actions.replyUrl) }]);
if (actions.contactWhatsApp) keyboard.inline_keyboard.push([{ text: '💬 WHATSAPP', url: String(actions.contactWhatsApp) }]);
return [{ json: { duplicate: false, httpStatus: 200, sendTelegram: true, photoMode, photoUrls, requestId, createdAt: payload.createdAt || null, validatedAt: new Date().toISOString(), text: lines.join('\n'), replyMarkup: keyboard.inline_keyboard.length ? keyboard : null, response: { ok: true, duplicate: false, requestId, photoCount: photoUrls.length } } }];
